mapper.select:
SELECT f.*, w.warehouse_name, w.warehouse_type, b.project_no, b.project_name, b.material_code, b.material_name, b.project_material_sku, b.material_category, b.color, b.model, b.uom, b.packaging_level FROM exception_event_fact f JOIN warehouse w ON w.warehouse_id = f.warehouse_id LEFT JOIN warehouse_sku_base b ON b.warehouse_sku_key = f.warehouse_sku_key
f.warehouse_id = #{warehouseId} AND f.area_id = #{areaId}
ORDER BY f.event_time DESC
